using System;using System.IO;using System.Text.Json;using System.Collections;using System.Collections.Generic;using Exoduser.UnityPort.Core;
class Program {
 static readonly List<object> Rows=new List<object>();static int failed;
 static void Check(bool ok,string name){Rows.Add(new{name,passed=ok});if(!ok)failed++;}
 static bool Near(double a,double b)=>Math.Abs(a-b)<.0001;
 static int Finish(string p){File.WriteAllText(p,JsonSerializer.Serialize(new{scope="standalone_dotnet_source_oracle_not_Unity_runtime",passed=failed==0,failed,checks=Rows},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("FEEDBACK_RESULT "+Rows.Count+" checks / "+failed+" failures");return failed==0?0:2;}
 static dynamic New(){var c=SourceStarterFixture.CreateKiSlash();c.StartX=10;c.StartY=20;c.EnemyAiEnabled=false;dynamic s=new Simulation(c);s.Random01=(Func<double>)(()=>.5);return s;}
 static List<dynamic> Drain(dynamic s){var a=new List<dynamic>();while(s.Feedback.Count>0){var f=s.Feedback.Dequeue();string k=f.Kind.ToString();if(k=="EnemyHit"||k=="EnemyCrit"||k=="EnemyDeath"||k=="BossHit"||k=="BossDeath"||k=="Roll"||k=="Parry")continue;a.Add(f);}return a;}   // RM-1 sound notifications (no state, no RNG) are not part of the ki slash packets
 static int Main(string[] args){
  Check(typeof(Simulation).GetField("Feedback")!=null,"native feedback queue exists");if(failed>0)return Finish(args[0]);
  using(var o=JsonDocument.Parse(File.ReadAllText(args[1]))){
   foreach(var row in o.RootElement.GetProperty("casts").EnumerateArray()){
    dynamic s=New();int n=0;s.Random01=(Func<double>)(()=>++n%2==1?.25:.75);s.Player.Facing=.3f;s.SpawnKiSlash(row.GetProperty("step").GetInt32(),120f);var a=Drain(s);var e=a[0];var ca=row.GetProperty("caller");var qu=row.GetProperty("queued");
    Check(a.Count==1&&e.Kind.ToString()=="Sample"&&e.SampleKey==ca.GetProperty("key").GetString()&&Near(e.Volume,ca.GetProperty("vol").GetDouble())&&Near(e.Rate,ca.GetProperty("rate").GetDouble())&&Near(e.QueuedRate,qu.GetProperty("rate").GetDouble())&&n==2,"original caller and queued pitch step"+row.GetProperty("step"));
   }
   dynamic full=New();for(int i=0;i<16;i++)full.SpawnKiSlash(1,0f);Drain(full);Check(full.SpawnKiSlash(2,0f)==null&&Drain(full).Count==1,"full pool still emits cast sample before failed allocation");
   dynamic charge=New();charge.Player.State="wWindup";charge.Player.StateTicks=999;charge.Player.KiChargeActive=true;charge.Player.KiChargeTicks=0;
   int calls=0;charge.Random01=(Func<double>)(()=>++calls%2==1?.25:.75);var collected=new List<dynamic>();
   for(int i=1;i<=150;i++){charge.Tick(0,0,100,20,true,false);var a=Drain(charge);collected.AddRange(a);if(i==39||i==79||i==119)Check(a.Count==0,"no early boundary event tick"+i);if(i==40||i==80){Check(a.Count==1&&a[0].SampleKey=="scarecrow_charge"&&Near(a[0].Volume,.35)&&Near(a[0].Rate,1)&&a[0].Tick==i,"charge tier sample tick"+i);}if(i==120){Check(a.Count==2&&a[0].SampleKey=="sword_parry"&&Near(a[0].Volume,.72)&&Near(a[0].Rate,1.08)&&a[1].Kind.ToString()=="KiChargeFlash"&&Near(a[1].Scale,.26)&&a[1].FrameTicks==2&&a[1].FrameCount==4,"full charge sample then original flash");}}
   Check(collected.Count==4&&calls==3&&charge.Player.KiChargeActive,"no repeated capped-charge sample and no auto release");charge.Tick(0,0,100,20,false,false);var released=Drain(charge);Check(released.Count==1&&released[0].SampleKey=="sword_swing3"&&released[0].Tier==3,"release emits charged third sample once");
   int chargeSample=0;foreach(var expected in o.RootElement.GetProperty("charges").EnumerateArray()){int tick=expected.GetProperty("tick").GetInt32();if(tick>120)continue;var callers=expected.GetProperty("caller");var sourceCaller=callers[callers.GetArrayLength()-1];var queue=expected.GetProperty("queue");var sourceQueued=queue[tick==120?0:queue.GetArrayLength()-1];dynamic actual=collected[chargeSample++];Check(actual.SampleKey==sourceCaller.GetProperty("key").GetString()&&Near(actual.Volume,sourceCaller.GetProperty("vol").GetDouble())&&Near(actual.Rate,sourceCaller.GetProperty("rate").GetDouble())&&Near(actual.QueuedRate,sourceQueued.GetProperty("rate").GetDouble()),"Node original charge packet and queued jitter tick"+tick);}
   dynamic simultaneous=New();simultaneous.Player.State="wWindup";simultaneous.Player.StateTicks=999;simultaneous.Player.KiChargeActive=true;simultaneous.Player.KiChargeTicks=119;simultaneous.Tick(0,0,100,20,false,false);var both=Drain(simultaneous);Check(both.Count==3&&both[0].SampleKey=="sword_parry"&&both[1].Kind.ToString()=="KiChargeFlash"&&both[2].SampleKey=="sword_swing3","boundary release preserves sample flash cast order");
   foreach(int step in new[]{1,3}){dynamic hit=New();var enemy=hit.SpawnNormalEnemy(40,20);hit.Player.Facing=0;hit.SpawnKiSlash(step,120f);Drain(hit);hit.Tick(0,0,100,20,false,false);var a=Drain(hit);Check(a.Count==1&&a[0].Kind.ToString()=="KiSlashHit"&&a[0].X==enemy.X&&a[0].Y==enemy.Y&&Near(a[0].Angle,0)&&Near(a[0].Size,step==3?404.8:140)&&a[0].FrameCount==4&&a[0].FrameTicks==3&&a[0].Ink&&a[0].InkCapacity==8&&!enemy.Alive,"source hit packet after lethal damage step"+step);hit.Tick(0,0,100,20,false,false);Check(Drain(hit).Count==0,"no duplicate hit sample or packet step"+step);}
   foreach(var sourceHit in o.RootElement.GetProperty("hits").EnumerateArray()){int step=sourceHit.GetProperty("step").GetInt32();dynamic hit=New();hit.SpawnNormalEnemy(40,20);hit.SpawnKiSlash(step,120f);Drain(hit);hit.Tick(0,0,100,20,false,false);var e=Drain(hit)[0];var shadow=sourceHit.GetProperty("shadows")[0];var vfx=sourceHit.GetProperty("events")[0].GetProperty("args");Check(Near(e.Size,shadow.GetProperty("size").GetDouble())&&e.SampleKey==vfx[0].GetString()&&Near(e.Size/256f,vfx[3].GetDouble())&&e.FrameTicks==vfx[4].GetInt32(),"Node original additive and ink size packet step"+step);}
   foreach(bool wall in new[]{true,false}){dynamic blocked=New();blocked.SpawnNormalEnemy(40,20);blocked.IsProjectileWall=(Func<float,float,bool>)((x,y)=>wall);blocked.HasLineOfSight=(Func<float,float,float,float,bool>)((x,y,xx,yy)=>false);blocked.SpawnKiSlash(1,0f);Drain(blocked);blocked.Tick(0,0,100,20,false,false);Check(Drain(blocked).Count==0,wall?"wall prevents hit feedback":"LOS prevents hit feedback");}
   // the cast pitch draw comes from the shared stream right before the next enemy: the cast takes the web number of draws (_r pitch + playSample rate jitter = casts[].randomCalls, 2) and the enemy equals one made from the same stream shifted by those draws (its own draw count and order belong to the enemy-spawn / c01 oracles, not to this check)
   dynamic rng=New();var values=new[]{.1,.2,.8,.9};int pos=0;rng.Random01=(Func<double>)(()=>values[(pos++)%4]);rng.SpawnKiSlash(1,0f);int castDraws=pos;var spawned=rng.SpawnNormalEnemy(100,100);
   int webCastDraws=o.RootElement.GetProperty("casts")[0].GetProperty("randomCalls").GetInt32();dynamic plain=New();int pos2=castDraws;plain.Random01=(Func<double>)(()=>values[(pos2++)%4]);var shifted=plain.SpawnNormalEnemy(100,100);
   Check(castDraws==webCastDraws&&spawned!=null&&shifted!=null&&pos-castDraws==pos2-castDraws&&spawned.Etype==shifted.Etype&&Near(spawned.Speed,shifted.Speed)&&spawned.Hp==shifted.Hp&&spawned.MaxHp==shifted.MaxHp,"shared cast pitch consumes RNG before enemy generation");
  }
  return Finish(args[0]);
 }
}
